var TrainingDateUtils = Class.create();
TrainingDateUtils.prototype = {
    initialize: function() {},

    getUniqueScheduleDates: function() {
        var uniqueDates = [];
        var seenDates = {};

        gs.info('Iniciando a consulta para obter datas de agendamento únicas.');

        var gr = new GlideRecord('x_1567520_shark_0_training_schedule');
        gr.query();

        if (!gr.hasNext()) {
            gs.info('Nenhum registro encontrado.');
        }

        while (gr.next()) {
            var scheduleDate = gr.getValue('schedule_date');
            gs.info('Processando data: ' + scheduleDate); 
            if (!seenDates[scheduleDate]) {
                seenDates[scheduleDate] = gr.getUniqueValue(); 
            }
        }

        gs.info('Processamento concluído. Total de datas únicas: ' + Object.keys(seenDates).length); 

        for (var date in seenDates) {
            uniqueDates.push(seenDates[date]); 
        }

        gs.info('Retornando sys_ids: ' + uniqueDates.join(',')); 

        return 'sys_idIN' + uniqueDates.join(',');
    },

    type: 'TrainingDateUtils'
};
